$scripts = @(
	{
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Type 'DWord' -Force -Value 0;
	};
	{
		Disable-ComputerRestore -Drive 'C:\';
	};
	{
		cmd.exe /c "rmdir C:\Windows.old";
	};
	{
		compact.exe /CompactOS:always;
	};
	{
		ie4uinit.exe -show;
	};
	{
		if (-not (Test-Path 'C:\Windows\System32\Recovery\winre.wim.keep')) {
			try {
				& reagentc.exe /disable | Out-Null;
				Remove-Item -Path 'C:\Windows\System32\Recovery\winre.wim' -Force -ErrorAction SilentlyContinue;
			} catch {}
		}
	};
	{
		# Radical RAM: Empty working set memory from setup processes and reclaim initialization heap
		try {
			$sig = @'
[DllImport("psapi.dll")]
public static extern int EmptyWorkingSet(IntPtr hwProc);
'@
			$psapi = Add-Type -MemberDefinition $sig -Name "PsapiMem" -Namespace "Win32" -PassThru -ErrorAction SilentlyContinue;
			if ($psapi) {
				Get-Process -ErrorAction SilentlyContinue | ForEach-Object {
					try { [Win32.PsapiMem]::EmptyWorkingSet($_.Handle) | Out-Null } catch {}
				};
			}
			[System.GC]::Collect();
			[System.GC]::WaitForPendingFinalizers();
		} catch {}
	};
	{
		# Radical RAM: Protected diagnostic and font cache services configured to Disabled (4) as SYSTEM
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\DPS" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WdiServiceHost" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\WdiSystemHost" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\FontCache" /v "Start" /t REG_DWORD /d 4 /f;
		reg.exe add "HKLM\SYSTEM\CurrentControlSet\Services\FontCache3.0.0.0" /v "Start" /t REG_DWORD /d 4 /f;
	};
);

